/* Chapter scenes and character whereabouts share one continuous geographic canvas. */
function chapterSettingRows(){return (A?.chapters||[]).filter(c=>c.chapter<=state.horizon).flatMap(c=>c.settings.map((s,i)=>({...s,id:`scene-${c.chapter}-${i}`,chapter:c.chapter,mode:c.mode})));}
function atlasRows(){const mode=filters.atlasMode||'chapter';if(mode==='chapter')return chapterSettingRows().filter(s=>s.chapter===state.horizon);if(mode==='story')return chapterSettingRows();const obs=selectedObservations();return (mode==='latest'?latestLocations(obs):obs).map(o=>({...o,id:'person-'+o.id,label:placeName(o.place),evidenceChapter:o.chapter}));}
function atlasPlace(id){return I.places.find(p=>p.id===id)||A.places.find(p=>p.id===id);}
function mappablePlace(p){return p&&p.kind!=='fictional'&&Number.isFinite(p.lon)&&Number.isFinite(p.lat);}
function atlasMap(rows){
 const mobile=compactNetwork(),w=mobile?360:900,h=mobile?390:490;
 const sites=[...new Set(rows.map(r=>r.place))].map(id=>atlasPlace(id)).filter(mappablePlace);
 const campaign=campaignAt(),showCampaign=filters.campaignLayer!=='off',bounds=[...sites,...(showCampaign?[...campaign.advance,...campaign.withdrawal].map(([lon,lat])=>({lon,lat})):[])];
 // One equirectangular world canvas. The camera fits the selected evidence.
 let left=-12,right=48,top=-67,bottom=-35;
 if(bounds.length){const xs=bounds.map(p=>p.lon),ys=bounds.map(p=>-p.lat);left=Math.min(...xs);right=Math.max(...xs);top=Math.min(...ys);bottom=Math.max(...ys);const cx=(left+right)/2,cy=(top+bottom)/2;let ww=Math.max(right-left+12,16),hh=Math.max(bottom-top+9,12);if(ww/hh<w/h)ww=hh*w/h;else hh=ww*h/w;left=cx-ww/2;right=cx+ww/2;top=cy-hh/2;bottom=cy+hh/2;}
 const xy=p=>[(p.lon-left)/(right-left)*w,(-p.lat-top)/(bottom-top)*h];
 let trails='';if(filters.atlasMode==='trail'){const groups={};for(const r of rows)(groups[r.character]??=[]).push(r);for(const rs of Object.values(groups))for(let i=1;i<rs.length;i++){const a=atlasPlace(rs[i-1].place),b=atlasPlace(rs[i].place);if(!mappablePlace(a)||!mappablePlace(b)||a.id===b.id)continue;const[x,y]=xy(a),[u,v]=xy(b);trails+=`<path d="M${x},${y} L${u},${v}" fill="none" stroke="#ad6743" stroke-width="2" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/>`;}}
 return `<div class="continuous-map" id="continuousMap"><div class="map-tools" aria-label="Map controls"><button data-map="in" aria-label="Zoom in">+</button><button data-map="out" aria-label="Zoom out">−</button><button data-map="fit">Fit map</button></div><svg id="atlasCanvas" viewBox="0 0 ${w} ${h}" data-width="${w}" data-height="${h}" tabindex="0" role="group" aria-label="Continuous map; drag to pan, pinch or use buttons to zoom"><rect x="-100000" y="-100000" width="200000" height="200000" fill="#e0e9e6"/>${G.map(f=>f.polygons.map(poly=>`<path class="geo" d="${poly.map((p,i)=>{const[x,y]=xy({lon:p[0],lat:p[1]});return(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)}).join('')}Z" vector-effect="non-scaling-stroke"/>`).join('')).join('')}${showCampaign?campaignOverlay(campaign,xy):''}${campaignCountries(xy)}${showCampaign?campaignTowns(campaign,xy):''}${trails}${sites.map((p,i)=>{const[x,y]=xy(p);return `<g class="atlas-marker" transform="translate(${x} ${y})" role="button" tabindex="0" data-action="atlasPlace" data-id="${p.id}" aria-label="Inspect ${esc(p.name)}"><g class="marker-symbol"><circle r="24" fill="transparent"/><circle r="15" fill="#fffaf0" stroke="#775d3f" stroke-width="2"/><text y="5" text-anchor="middle" font-size="14" fill="#374c39">${i+1}</text></g></g>`}).join('')}</svg>${filters.atlasMode==='chapter'&&rows.some(r=>!mappablePlace(atlasPlace(r.place)))?`<div class="unpinned-map-note"><strong>Setting without a precise pin</strong>${rows.filter(r=>!mappablePlace(atlasPlace(r.place))).map(r=>`<span>${esc(r.label)}</span>`).join('')}</div>`:''}<div class="map-gesture-hint">Drag to pan · pinch to zoom · tap a numbered place</div></div>${sites.length?`<div class="map-site-key">${sites.map((p,i)=>`<button data-action="atlasPlace" data-id="${p.id}"><b>${i+1}</b>${esc(p.name)}</button>`).join('')}</div>`:''}`;
}
function settingCard(r){const p=atlasPlace(r.place),unpinned=!mappablePlace(p);return `<article class="setting-card"><div><span class="eyebrow">${r.character?esc(name(r.character)):r.mode==='historical'?'Historical discussion':r.mode==='uncertain'?'Setting uncertain':'Scene setting'}${unpinned?' · unpinned':''}</span><h2>${esc(r.label||p?.name||r.place)}</h2><p>${esc(r.note)}</p><small>${chLabel(r.chapter)}${r.evidenceChapter&&r.evidenceChapter!==r.chapter?' · scene continuity from '+chLabel(r.evidenceChapter):''}</small></div><button class="compact" data-action="atlasEvidence" data-id="${r.id}">Evidence ↗</button></article>`;}
function chapterAtlas(){const mode=filters.atlasMode||'chapter',rows=atlasRows(),current=A.chapters.find(c=>c.chapter===state.horizon),people=['latest','trail'].includes(mode),unpinned=[...new Set(rows.filter(r=>!mappablePlace(atlasPlace(r.place))).map(r=>r.place))];let shown=rows;if(mode==='story'){shown=[...new Map(rows.map(r=>[r.place,r])).values()];}
 return `<div class="workspace-heading"><div><span class="eyebrow">The geography of the telling</span><h1>Atlas</h1></div><span class="scope-badge">${chLabel(state.horizon)}</span></div><div class="network-toolbar"><label>Map layer<select data-filter="atlasMode" aria-label="Map layer"><option value="chapter" ${mode==='chapter'?'selected':''}>This chapter’s settings</option><option value="story" ${mode==='story'?'selected':''}>Settings visited so far</option><option value="latest" ${mode==='latest'?'selected':''}>Characters: last recorded</option><option value="trail" ${mode==='trail'?'selected':''}>Characters: trails</option></select></label>${people?`<label>Follow${charSelect()}</label>`:''}<label>French campaign<select data-filter="campaignLayer" aria-label="French campaign"><option value="on" ${filters.campaignLayer!=='off'?'selected':''}>At chapter opening</option><option value="off" ${filters.campaignLayer==='off'?'selected':''}>Hide shading</option></select></label></div>${filters.campaignLayer!=='off'?campaignPanel(campaignAt()):''}${mode==='chapter'?`<div class="chapter-setting-heading"><strong>${rows.length?rows.map(r=>esc(r.label||atlasPlace(r.place)?.name)).join(' · '):current?.mode==='essay'?'Essay / no single scene setting':'No confidently established setting'}</strong><p>${current?.mode==='historical'?'This chapter discusses historical events across these locations.':current?.mode==='essay'?'This chapter develops an argument rather than a geographically situated scene.':''}</p></div>`:''}${atlasMap(rows)}<p class="mapcaption">${mode==='trail'?'Dashed lines link character observations in reading order, not reconstructed travel routes. ':people?'Last recorded does not establish continued presence. ':mode==='story'?'Places established as settings through the selected chapter. ':''}Period country names on a border-free geographic base. Shading shows approximate campaign corridors; pins locate towns or named areas, not exact buildings.${unpinned.length?' '+unpinned.length+' setting'+(unpinned.length===1?' is':'s are')+' listed below without a precise pin.':''}</p>${rows.length?`<div class="setting-cards">${shown.map(settingCard).join('')}</div>`:empty(people?'No sourced character sighting for this selection. Choose “This chapter’s settings” to see the scene location.':'No geographic point is asserted for this chapter. The map remains available to explore.')}<details class="network-evidence"><summary>What this map represents</summary><p>Chapter settings are editorial readings of the Maude text, with paragraph evidence. A scene may continue after its location was established; those entries cite the earlier passage and explain continuity. A place merely mentioned in dialogue is not a scene setting. Fictional estates and locations without supported coordinates remain named, unpinned entries.</p><p>Character sightings are a separate selective layer. Chapter settings do not imply that every character mentioned is physically present.</p></details>${campaignSources()}${projectionBar()}`;
}
function bindAtlasMap(svg=$('#atlasCanvas'),wrap=$('#continuousMap')){if(!svg)return;const W=+svg.dataset.width,H=+svg.dataset.height;let v=[0,0,W,H],pointers=new Map(),gesture=null,moved=false;
 const paint=()=>{svg.setAttribute('viewBox',v.join(' '));svg.querySelectorAll('.marker-symbol').forEach(g=>g.setAttribute('transform',`scale(${v[2]/W})`));};
 const zoom=(factor,px=.5,py=.5)=>{const nw=Math.max(W/32,Math.min(W*8,v[2]*factor)),nh=nw*H/W;v=[v[0]+(v[2]-nw)*px,v[1]+(v[3]-nh)*py,nw,nh];paint();};
 wrap.querySelectorAll('[data-map]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(b.dataset.map==='fit'){v=[0,0,W,H];paint()}else zoom(b.dataset.map==='in'?.65:1/.65)});
 const start=()=>{const ps=[...pointers.values()];gesture={v:[...v],ps,rect:svg.getBoundingClientRect()};};
 svg.onpointerdown=e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1)moved=false;start();};
 svg.onpointermove=e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const ps=[...pointers.values()],old=gesture.ps,r=gesture.rect;if(ps.length!==old.length)return;const dx=ps[0].x-old[0].x,dy=ps[0].y-old[0].y;if(Math.abs(dx)+Math.abs(dy)>5||ps.length>1)moved=true;if(!moved)return;svg.setPointerCapture(e.pointerId);closePeek();if(ps.length===1)v=[gesture.v[0]-dx/r.width*gesture.v[2],gesture.v[1]-dy/r.height*gesture.v[3],gesture.v[2],gesture.v[3]];else{const d=Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y),od=Math.hypot(old[0].x-old[1].x,old[0].y-old[1].y)||1,nw=Math.max(W/32,Math.min(W*8,gesture.v[2]*od/Math.max(d,1))),nh=nw*H/W,ox=((old[0].x+old[1].x)/2-r.left)/r.width,oy=((old[0].y+old[1].y)/2-r.top)/r.height,nx=((ps[0].x+ps[1].x)/2-r.left)/r.width,ny=((ps[0].y+ps[1].y)/2-r.top)/r.height;v=[gesture.v[0]+ox*gesture.v[2]-nx*nw,gesture.v[1]+oy*gesture.v[3]-ny*nh,nw,nh];}paint();};
 const end=e=>{pointers.delete(e.pointerId);if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);start();};svg.onpointerup=end;svg.onpointercancel=end;
 svg.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopImmediatePropagation();moved=false}},true);
 svg.onwheel=e=>{e.preventDefault();const r=svg.getBoundingClientRect();zoom(e.deltaY>0?1.15:1/1.15,(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height)};
 svg.onkeydown=e=>{if(e.target!==svg)return;if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key)){e.preventDefault();e.stopPropagation();if(e.key==='Home')v=[0,0,W,H];else if(['+','=','-'].includes(e.key))zoom(e.key==='-'?1.3:1/1.3);else{v[0]+=(e.key==='ArrowLeft'?-.15:e.key==='ArrowRight'?.15:0)*v[2];v[1]+=(e.key==='ArrowUp'?-.15:e.key==='ArrowDown'?.15:0)*v[3];}paint();}};
}
function installChapterAtlas(){filters.atlasMode='chapter';views.atlas=chapterAtlas;const nav=navs.find(n=>n[0]==='atlas');if(nav)nav[2]='Atlas';const previousBind=bindWorkspace;bindWorkspace=function(){previousBind();bindAtlasMap()};const previousAction=action;action=function(el){const a=el.dataset.action;if((a==='project'||a==='projectPerson')&&el.dataset.target==='atlas')filters.atlasMode=(el.dataset.id||filters.character)?'latest':'chapter';if(a==='campaignEvidence'){const c=campaignAt();if(c.id!==el.dataset.id||c.paragraph===undefined||c.after>=state.horizon)return;openWorkspacePeek(el,`<span class="eyebrow">Campaign evidence · before this chapter</span><h3 id="peek-title">${esc(c.title)}</h3>${peekCitation(c.after,c.paragraph)}<p class="peek-meta">The route is a historical approximation. This passage anchors the chapter at which the campaign phase becomes available.</p>`)}else if(a==='atlasEvidence'){const r=atlasRows().find(r=>r.id===el.dataset.id);if(!r)return;openWorkspacePeek(el,`<span class="eyebrow">Setting evidence · ${chLabel(r.chapter)}</span><h3 id="peek-title">${esc(r.label||atlasPlace(r.place)?.name)}</h3><p>${esc(r.note)}</p>${peekCitation(r.evidenceChapter||r.chapter,r.paragraph)}${r.evidenceChapter&&r.evidenceChapter!==r.chapter?`<p class="peek-meta">The location is established in an earlier chapter; the selected chapter continues that scene.</p>`:''}`)}else if(a==='atlasPlace'){const rs=atlasRows().filter(r=>r.place===el.dataset.id),p=atlasPlace(el.dataset.id);openWorkspacePeek(el,`<span class="eyebrow">${filters.atlasMode==='chapter'?'This chapter':'Through '+chLabel(state.horizon)}</span><h3 id="peek-title">${esc(p?.name||rs[0]?.label)}</h3>${p?.coordinateSource?`<a class="textbutton" href="${esc(p.coordinateSource)}" target="_blank" rel="noopener noreferrer">Coordinate source ↗</a>`:''}${rs.map(r=>`<div class="peek-record"><strong>${r.character?esc(name(r.character))+' · ':''}${chLabel(r.chapter)}</strong><p>${esc(r.note)}</p>${peekCitation(r.evidenceChapter||r.chapter,r.paragraph)}</div>`).join('')}`)}else previousAction(el);};}

